import React, { useState, useEffect } from "react";
import api from "../api";
import Container from "react-bootstrap/esm/Container";
import Card from "react-bootstrap/Card";

const MyBooks = () => {
  const [books, setBooks] = useState([]);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [image, setImage] = useState(null);

  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const response = await api.get("/api/my-books", {
          headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
        });
        setBooks(response.data);
      } catch (err) {
        console.error("Error fetching books:", err);
      }
    };
    fetchBooks();
  }, []);

  const handleCreateBook = async () => {
    const formData = new FormData();
    formData.append("title", title);
    formData.append("content", content);
    if (image) {
      formData.append("image", image); // Attach the image file if selected
    }

    try {
      await api.post("/api/create-book", formData, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setTitle("");
      setContent("");
      setImage(null);
      // Refresh the list of books
      const response = await api.get("/api/my-books", {
        headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
      });
      setBooks(response.data);
    } catch (err) {
      console.error("Error creating book:", err);
    }
  };

  return (
    <Container>
      <h2>My Books</h2>
      <Container>
        {books.map((book) => (
          <Card style={{ width: "18rem" }}>
            <Card.Img
              variant="top"
              src={`http://127.0.0.1:5000/uploads/${book.image}`}
              alt={book.title}
            />
            <Card.Body>
              <Card.Title>{book.title}</Card.Title>
              <Card.Text>{book.content.substring(0, 100)}</Card.Text>
            </Card.Body>
          </Card>
        ))}
      </Container>

      <h3>Create a New Book</h3>
      <input
        type="text"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        placeholder="Title"
        required
      />
      <textarea
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Content"
        required
      ></textarea>
      <input
        type="file"
        onChange={(e) => setImage(e.target.files[0])}
        accept="image/*"
      />
      <button onClick={handleCreateBook}>Create Book</button>
    </Container>
  );
};

export default MyBooks;
